  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}

