137	  const parsed = parseBoardCode(value.boardCode);
138	  if (!parsed || parsed.size !== size) return null;
139	  const players = readPair(value.players, (entry) => readPlayer(entry, count, true));
140	  const results = readPair(value.results, (entry) => readResult(entry, size));
141	  const winner = readPlayer(value.winner, count, true);
142	  if (!players || !results || winner === undefined) return null;
143	  if (results.some((result, index) => result !== null && players[index] === null)) return null;
144	  if (winner) {
145	    if (!players[0] || !players[1] || !results[0] || !results[1]) return null;
146	    if (!samePlayer(winner, compareResults(players[0], results[0], players[1], results[1]))) return null;
147	  } else if (results[0] && results[1]) return null;
148	  return { boardCode: value.boardCode, players, results, winner };
149	}
150	
151	function readCurrent(
152	  value: unknown,
153	  rounds: readonly TournamentRound[],
154	): Tournament['current'] | undefined {
155	  if (value === null) return null;
156	  if (
157	    !isJsonObject(value) ||
158	    !hasExactKeys(value, ['match', 'round', 'turn']) ||
159	    !isNonnegativeSafeInteger(value.round) ||
160	    !isNonnegativeSafeInteger(value.match) ||
161	    (value.turn !== 0 && value.turn !== 1) ||
162	    !rounds[value.round]?.matches[value.match]
163	  )
164	    return undefined;
165	  return { match: value.match, round: value.round, turn: value.turn };
166	}
167	
168	function validPairings(
169	  entrants: readonly TournamentPlayer[],
170	  rounds: readonly TournamentRound[],
171	  count: TournamentPlayerCount,
172	): boolean {
173	  const first = rounds[0]?.matches;
174	  const pairs = openingSeedPairs(count);
175	  if (!first || first.length !== pairs.length) return false;
176	  for (let index = 0; index < pairs.length; index += 1) {
177	    const match = first[index]!;
178	    const pair = pairs[index]!;
179	    if (!sameNullablePlayer(match.players[0], entrants[pair[0] - 1]!) ||
180	      !sameNullablePlayer(match.players[1], entrants[pair[1] - 1]!)) return false;
181	  }
182	  for (let round = 1; round < rounds.length; round += 1) {
183	    for (let matchIndex = 0; matchIndex < rounds[round]!.matches.length; matchIndex += 1) {
184	      const previous = rounds[round - 1]!.matches;
185	      const match = rounds[round]!.matches[matchIndex]!;
186	      if (!sameNullablePlayer(match.players[0], previous[matchIndex * 2]?.winner ?? null) ||
187	        !sameNullablePlayer(match.players[1], previous[matchIndex * 2 + 1]?.winner ?? null)) return false;
188	    }
189	  }
190	  return true;
191	}
192	
193	function validProgress(tournament: Tournament): boolean {
194	  const positions = tournament.rounds.flatMap((round, roundIndex) =>
195	    round.matches.map((match, matchIndex) => ({ match, matchIndex, roundIndex })),
196	  );
197	  if (tournament.status === 'complete') {
198	    const lastRound = tournament.rounds.at(-1);
199	    const finalWinner = lastRound?.matches[0]?.winner;
200	    return (
201	      tournament.current === null &&
202	      tournament.champion !== null &&
203	      positions.every(({ match }) => match.winner !== null) &&
204	      !!finalWinner &&
205	      samePlayer(tournament.champion, finalWinner)
206	    );
207	  }
208	  const current = tournament.current;
209	  if (!current || tournament.champion !== null) return false;
210	  const currentIndex = positions.findIndex(
211	    (position) => position.roundIndex === current.round && position.matchIndex === current.match,
212	  );
213	  const activeMatch = positions[currentIndex]?.match;
214	  if (currentIndex < 0 || !activeMatch?.players[0] || !activeMatch.players[1]) return false;
215	  if (positions.slice(0, currentIndex).some(({ match }) => match.winner === null)) return false;
216	  if (positions.slice(currentIndex + 1).some(({ match }) => match.winner || match.results.some(Boolean))) return false;
217	  if (current.turn === 0) return !activeMatch.results[1] && !activeMatch.winner;
218	  return !!activeMatch.results[0] && (!activeMatch.winner || current.round < tournament.rounds.length - 1);
219	}
220	
221	function samePlayer(first: TournamentPlayer, second: TournamentPlayer): boolean {
222	  return first.seed === second.seed && first.name === second.name;
223	}
224	
225	function sameNullablePlayer(
226	  first: TournamentPlayer | null,
227	  second: TournamentPlayer | null,
228	): boolean {
229	  return first === null ? second === null : second !== null && samePlayer(first, second);
230	}

