export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FORMAT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 65_536;

export interface TournamentTransfer {
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly tournament: Tournament | null;
}

export function encodeTournament(transfer: TournamentTransfer): string {
  const value = {
    draft: transfer.draft,
    format: TOURNAMENT_FORMAT,
    gameSnapshot: transfer.gameSnapshot,
    tournament: transfer.tournament,
    version: TOURNAMENT_FORMAT_VERSION,
  };
  return JSON.stringify(sortKeys(value), null, 2);
}

export function decodeTournament(text: string): TournamentTransfer | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['draft', 'format', 'gameSnapshot', 'tournament', 'version']) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    !validDraft(value.draft)
  )
    return null;
  if (value.tournament !== null && !isValidTournament(value.tournament)) return null;
  if (value.gameSnapshot !== null && typeof value.gameSnapshot !== 'string') return null;
  if (typeof value.gameSnapshot === 'string') {
    if (value.gameSnapshot.length > SNAPSHOT_MAX_BYTES) return null;
    const game = decodeSnapshot(value.gameSnapshot);
    const tournament = value.tournament as Tournament | null;
    const match = tournament ? currentMatch(tournament) : null;
    const position = tournament?.current;
    if (
      !game ||
      !tournament ||
      tournament.status !== 'active' ||
      !position ||
      !match ||
      match.results[position.turn] !== null ||
      game.boardCode !== match.boardCode
    )
      return null;
    // A completed snapshot is allowed only for the current unfinished attempt. Loading it will
    // record the same visible result through the ordinary completion boundary.
    if (isWon(game) && !game.started) return null;
  }
  return {
    draft: value.draft,
    gameSnapshot: value.gameSnapshot,
    tournament: value.tournament as Tournament | null,
  };
}

function validDraft(value: unknown): value is TournamentDraft {
  return (
    isJsonObject(value) &&
    hasExactKeys(value, ['playerCount', 'players']) &&
    typeof value.playerCount === 'number' &&
    isPlayerCount(value.playerCount) &&
    Array.isArray(value.players) &&
    value.players.length === 8 &&
    value.players.every((name) => typeof name === 'string')
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) sorted[key] = sortKeys((value as Record<string, unknown>)[key]);
  return sorted;
}
import { useState } from 'react';
import type { Dispatch, MutableRefObject, SetStateAction } from 'react';
import { decodeTournament, encodeTournament, TOURNAMENT_MAX_BYTES } from './tournament-format.ts';
import type { Tournament, TournamentDraft, TournamentResult } from './tournament.ts';
import type { TournamentTurnHandle } from './TournamentTurn.tsx';

export type TournamentDialogAction = 'leave' | 'load' | null;

export interface TournamentExchangeOptions {
  readonly draft: TournamentDraft;
  readonly history: readonly Tournament[];
  readonly onBack: () => void;
  readonly result: TournamentResult | null;
  readonly setAutoFocusBoard: Dispatch<SetStateAction<boolean>>;
  readonly setDraft: Dispatch<SetStateAction<TournamentDraft>>;
  readonly setGameFeedback: Dispatch<SetStateAction<{ readonly key: string; readonly number: number; readonly text: string }>>;
  readonly setGameSnapshot: Dispatch<SetStateAction<string | null>>;
  readonly setSaveWhenComplete: Dispatch<SetStateAction<boolean>>;
  readonly setStartButtonVisible: Dispatch<SetStateAction<boolean>>;
  readonly setTournament: Dispatch<SetStateAction<Tournament | null>>;
  readonly setTurnStarted: Dispatch<SetStateAction<boolean>>;
  readonly tournament: Tournament | null;
  readonly turnRef: MutableRefObject<TournamentTurnHandle | null>;
  readonly turnStarted: boolean;
}

export function useTournamentExchange(options: TournamentExchangeOptions) {
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState({ message: '', number: 0 });
  const [dialogAction, setDialogAction] = useState<TournamentDialogAction>(null);
  const [pendingTransfer, setPendingTransfer] = useState<ReturnType<typeof decodeTournament>>(null);

  function publish(message: string): void {
    setNotice((previous) => ({ message, number: previous.number + 1 }));
  }

  function clearNotice(): void {
    setNotice((previous) => ({ ...previous, message: '' }));
  }

  function exportCurrent(): void {
    const tournament = options.tournament ?? options.history[0] ?? null;
    const gameSnapshot =
      options.tournament && options.result === null && options.turnStarted
        ? options.turnRef.current?.exportSnapshot() ?? null
        : null;
    const output = encodeTournament({ draft: options.draft, gameSnapshot, tournament });
    if (new TextEncoder().encode(output).byteLength > TOURNAMENT_MAX_BYTES) {
      publish('Tournament export is too large.');
      return;
    }
    setJson(output);
    publish('Tournament exported to the JSON box.');
  }

  function loadFromJson(): void {
    const transfer = decodeTournament(json);
    if (!transfer) {
      publish('Invalid tournament JSON.');
      return;
    }
    if (options.tournament?.status === 'active') {
      setPendingTransfer(transfer);
      setDialogAction('load');
      return;
    }
    applyTransfer(transfer);
  }

  function applyTransfer(transfer: NonNullable<ReturnType<typeof decodeTournament>>): void {
    options.setDraft(transfer.draft);
    options.setTournament(transfer.tournament);
    options.setGameSnapshot(transfer.gameSnapshot);
    options.setTurnStarted(transfer.gameSnapshot !== null);
    options.setStartButtonVisible(false);
    options.setAutoFocusBoard(false);
    options.setSaveWhenComplete(false);
    options.setGameFeedback({ key: '', number: 0, text: '' });
    publish('Tournament loaded.');
  }

  function requestLeave(): void {
    setDialogAction('leave');
  }

  function cancelDialog(): void {
    setDialogAction(null);
    setPendingTransfer(null);
  }

  function confirmDialog(): void {
    const action = dialogAction;
    setDialogAction(null);
    if (action === 'leave') {
      options.setTournament(null);
      options.setGameSnapshot(null);
      options.setTurnStarted(false);
      options.setSaveWhenComplete(false);
      options.onBack();
      return;
    }
    if (action === 'load' && pendingTransfer) applyTransfer(pendingTransfer);
    setPendingTransfer(null);
  }

  return {
    cancelDialog,
    clearNotice,
    confirmDialog,
    dialogAction,
    exportCurrent,
    json,
    loadFromJson,
    notice,
    publish,
    requestLeave,
    setJson,
  };
}

import { useEffect, useRef, useState } from 'react';
import type { Dispatch, RefObject, SetStateAction } from 'react';
import { currentMatch, type Tournament, type TournamentDraft, type TournamentResult } from './tournament.ts';
import {
  browserTournamentStore,
  readTournamentHistory,
  writeTournamentHistory,
  type TournamentStore,
} from './tournament-storage.ts';
import { tournamentStatusKey, tournamentStatusText } from './tournament-status.ts';
import { useTournamentExchange, type TournamentDialogAction } from './use-tournament-exchange.ts';
import { useTournamentPlay } from './use-tournament-play.ts';
import type { TournamentTurnHandle } from './TournamentTurn.tsx';

export interface TournamentController {
  readonly actionLabel: string | null;
  readonly activeTurnKey: string;
  readonly autoFocusBoard: boolean;
  readonly current: Tournament['current'];
  readonly dialogAction: TournamentDialogAction;
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly history: readonly Tournament[];
  readonly json: string;
  readonly match: ReturnType<typeof currentMatch>;
  readonly notice: string;
  readonly player: Tournament['entrants'][number] | null;
  readonly result: TournamentResult | null;
  readonly setDraft: Dispatch<SetStateAction<TournamentDraft>>;
  readonly setJson: Dispatch<SetStateAction<string>>;
  readonly startButtonVisible: boolean;
  readonly status: string;
  readonly statusKey: string;
  readonly storageAvailable: boolean;
  readonly tournament: Tournament | null;
  readonly turn: RefObject<TournamentTurnHandle | null>;
  readonly turnStarted: boolean;
  cancelDialog(): void;
  confirmDialog(): void;
  exportCurrent(): void;
  loadFromJson(): void;
  onBoardFocused(): void;
  onComplete(result: TournamentResult): void;
  onFeedback(text: string, number: number): void;
  requestLeave(): void;
  startTournament(): void;
  turnAction(): void;
}

export function useTournament(onBack: () => void): TournamentController {
  const [store] = useState<TournamentStore | null>(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly Tournament[]>(initialHistory.items);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const play = useTournamentPlay();
  const turn = useRef<TournamentTurnHandle>(null);

  useEffect(() => {
    if (!play.saveWhenComplete || play.tournament?.status !== 'complete') return;
    const next = [play.tournament, ...history].slice(0, 10);
    setHistory(next);
    setStorageAvailable(writeTournamentHistory(store, next));
    play.setSaveWhenComplete(false);
  }, [history, play.saveWhenComplete, play.setSaveWhenComplete, play.tournament, store]);

  const current = play.current;
  const match = play.match;
  const player = play.player;
  const result = play.result;
  const activeTurnKey = current ? `${current.round}-${current.match}-${current.turn}` : '';
  const turnKeyRef = useRef('');
  turnKeyRef.current = activeTurnKey;
  const exchange = useTournamentExchange({
    draft: play.draft,
    history,
    onBack,
    result,
    setAutoFocusBoard: play.setAutoFocusBoard,
    setDraft: play.setDraft,
    setGameFeedback: play.setGameFeedback,
    setGameSnapshot: play.setGameSnapshot,
    setSaveWhenComplete: play.setSaveWhenComplete,
    setStartButtonVisible: play.setStartButtonVisible,
    setTournament: play.setTournament,
    setTurnStarted: play.setTurnStarted,
    tournament: play.tournament,
    turnRef: turn,
    turnStarted: play.turnStarted,
  });
  const onFeedback = (text: string, number: number): void => {
    play.setGameFeedback({ key: turnKeyRef.current, number, text });
    exchange.clearNotice();
  };
  const startTournament = (): void => play.startTournament(exchange.publish, exchange.clearNotice);
  const turnAction = (): void => play.turnAction(exchange.clearNotice);

  const actionLabel = play.tournament?.status === 'active'
    ? match?.winner
      ? 'Next match'
      : current?.turn === 0 && match?.results[0]
        ? 'Next turn'
        : !play.turnStarted || play.startButtonVisible
          ? 'Start turn'
          : null
    : null;
  const status = tournamentStatusText(
    play.tournament,
    player,
    match,
    current,
    result,
    play.gameFeedback,
    activeTurnKey,
    exchange.notice.message,
  );
  const statusKey = tournamentStatusKey(
    play.tournament,
    player,
    match,
    current,
    result,
    play.gameFeedback,
    activeTurnKey,
    exchange.notice,
  );

  return {
    actionLabel,
    activeTurnKey,
    autoFocusBoard: play.autoFocusBoard,
    cancelDialog: exchange.cancelDialog,
    confirmDialog: exchange.confirmDialog,
    current,
    dialogAction: exchange.dialogAction,
    draft: play.draft,
    exportCurrent: exchange.exportCurrent,
    gameSnapshot: play.gameSnapshot,
    history,
    json: exchange.json,
    loadFromJson: exchange.loadFromJson,
    match,
    notice: exchange.notice.message,
    onBoardFocused: play.onBoardFocused,
    onComplete: play.onComplete,
    onFeedback,
    player,
    requestLeave: exchange.requestLeave,
    result,
    setDraft: play.setDraft,
    setJson: exchange.setJson,
    startButtonVisible: play.startButtonVisible,
    startTournament,
    status,
    statusKey,
    storageAvailable,
    tournament: play.tournament,
    turn,
    turnAction,
    turnStarted: play.turnStarted,
  };
}
import { useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { newTournament } from './new-tournament.ts';
import {
  advanceTournamentMatch,
  advanceTournamentTurn,
  currentMatch,
  currentPlayer,
  currentResult,
  type Tournament,
  type TournamentDraft,
  type TournamentResult,
} from './tournament.ts';
import { recordTournamentResult } from './tournament-results.ts';
import type { TournamentFeedback } from './tournament-status.ts';

const EMPTY_DRAFT: TournamentDraft = { playerCount: 4, players: ['', '', '', '', '', '', '', ''] };

export interface TournamentPlayState {
  readonly autoFocusBoard: boolean;
  readonly current: Tournament['current'];
  readonly draft: TournamentDraft;
  readonly gameFeedback: TournamentFeedback;
  readonly gameSnapshot: string | null;
  readonly match: ReturnType<typeof currentMatch>;
  readonly player: Tournament['entrants'][number] | null;
  readonly result: TournamentResult | null;
  readonly saveWhenComplete: boolean;
  readonly setAutoFocusBoard: Dispatch<SetStateAction<boolean>>;
  readonly setDraft: Dispatch<SetStateAction<TournamentDraft>>;
  readonly setGameFeedback: Dispatch<SetStateAction<TournamentFeedback>>;
  readonly setGameSnapshot: Dispatch<SetStateAction<string | null>>;
  readonly setSaveWhenComplete: Dispatch<SetStateAction<boolean>>;
  readonly setStartButtonVisible: Dispatch<SetStateAction<boolean>>;
  readonly setTournament: Dispatch<SetStateAction<Tournament | null>>;
  readonly setTurnStarted: Dispatch<SetStateAction<boolean>>;
  readonly startButtonVisible: boolean;
  readonly tournament: Tournament | null;
  readonly turnStarted: boolean;
  onBoardFocused(): void;
  onComplete(result: TournamentResult): void;
  startTournament(publish: (message: string) => void, clearNotice: () => void): void;
  turnAction(clearNotice: () => void): void;
}

export function useTournamentPlay(): TournamentPlayState {
  const [draft, setDraft] = useState<TournamentDraft>(EMPTY_DRAFT);
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [gameSnapshot, setGameSnapshot] = useState<string | null>(null);
  const [turnStarted, setTurnStarted] = useState(false);
  const [startButtonVisible, setStartButtonVisible] = useState(false);
  const [autoFocusBoard, setAutoFocusBoard] = useState(false);
  const [gameFeedback, setGameFeedback] = useState<TournamentFeedback>({ key: '', number: 0, text: '' });
  const [saveWhenComplete, setSaveWhenComplete] = useState(false);

  const current = tournament?.current ?? null;
  const match = tournament ? currentMatch(tournament) : null;
  const player = tournament ? currentPlayer(tournament) : null;
  const result = tournament ? currentResult(tournament) : null;

  function startTournament(publish: (message: string) => void, clearNotice: () => void): void {
    const started = newTournament(draft.players, draft.playerCount);
    if (!('tournament' in started)) {
      publish(started.error);
      return;
    }
    const players = [...draft.players];
    started.names.forEach((name, index) => { players[index] = name; });
    setDraft({ ...draft, players });
    setTournament(started.tournament);
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setSaveWhenComplete(true);
    clearNotice();
    setGameFeedback({ key: '', number: 0, text: '' });
  }

  function startTurn(clearNotice: () => void): void {
    setGameSnapshot(null);
    setTurnStarted(true);
    setStartButtonVisible(true);
    setAutoFocusBoard(true);
    clearNotice();
  }

  function onBoardFocused(): void {
    setAutoFocusBoard(false);
    setStartButtonVisible(false);
  }

  function onComplete(completed: TournamentResult): void {
    setTournament((previous) => previous ? recordTournamentResult(previous, completed) : previous);
  }

  function turnAction(clearNotice: () => void): void {
    if (!tournament) return;
    if (match?.winner) {
      setTournament(advanceTournamentMatch(tournament));
      resetTurnView(clearNotice);
    } else if (current?.turn === 0 && match?.results[0]) {
      setTournament(advanceTournamentTurn(tournament));
      resetTurnView(clearNotice);
    } else if (!turnStarted) startTurn(clearNotice);
  }

  function resetTurnView(clearNotice: () => void): void {
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setGameFeedback({ key: '', number: 0, text: '' });
    clearNotice();
  }

  return {
    autoFocusBoard,
    current,
    draft,
    gameFeedback,
    gameSnapshot,
    match,
    onBoardFocused,
    onComplete,
    player,
    result,
    saveWhenComplete,
    setAutoFocusBoard,
    setDraft,
    setGameFeedback,
    setGameSnapshot,
    setSaveWhenComplete,
    setStartButtonVisible,
    setTournament,
    setTurnStarted,
    startButtonVisible,
    startTournament,
    tournament,
    turnAction,
    turnStarted,
  };
}

import { formatElapsed } from '../elapsed-time.ts';
import type { Tournament, TournamentMatch, TournamentPlayer } from './tournament.ts';

interface TournamentBracketProps {
  readonly current: Tournament['current'];
  readonly rounds: Tournament['rounds'];
}

export function TournamentBracket({ current, rounds }: TournamentBracketProps) {
  return (
    <section className="tournament-bracket" aria-labelledby="tournament-bracket-title">
      <h3 id="tournament-bracket-title">Bracket</h3>
      {rounds.map((round, roundIndex) => (
        <div className="tournament-table-scroll" key={round.name}>
          <table className="tournament-table">
            <caption>{round.name}</caption>
            <thead>
              <tr>
                <th scope="col">Match</th>
                <th scope="col">Player</th>
                <th scope="col">Moves</th>
                <th scope="col">Time</th>
                <th scope="col">Winner</th>
              </tr>
            </thead>
            {round.matches.map((match, matchIndex) => (
              <tbody
                key={match.boardCode}
                className={current?.round === roundIndex && current.match === matchIndex ? 'current-match' : undefined}
              >
                {[0, 1].map((playerIndex) => (
                  <MatchPlayerRow
                    key={playerIndex}
                    isCurrent={current?.round === roundIndex && current.match === matchIndex}
                    match={match}
                    matchIndex={matchIndex}
                    playerIndex={playerIndex as 0 | 1}
                  />
                ))}
              </tbody>
            ))}
          </table>
        </div>
      ))}
    </section>
  );
}

interface MatchPlayerRowProps {
  readonly isCurrent: boolean;
  readonly match: TournamentMatch;
  readonly matchIndex: number;
  readonly playerIndex: 0 | 1;
}

function MatchPlayerRow({ isCurrent, match, matchIndex, playerIndex }: MatchPlayerRowProps) {
  const player: TournamentPlayer | null = match.players[playerIndex];
  const result = match.results[playerIndex];
  return (
    <tr>
      {playerIndex === 0 && (
        <th scope="rowgroup" rowSpan={2}>
          Match {matchIndex + 1}{isCurrent ? ' (Current)' : ''}
        </th>
      )}
      <th scope="row">{player ? `${player.name} (Seed ${player.seed})` : 'TBD'}</th>
      <td>{result?.moves ?? '—'}</td>
      <td>
        {result ? `${formatElapsed(result.elapsedMs)} (${result.elapsedMs.toFixed(3)} ms)` : '—'}
      </td>
      {playerIndex === 0 && <td rowSpan={2}>{match.winner?.name ?? '—'}</td>}
    </tr>
  );
}
import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { normalizeName, openingSeedPairs, type Tournament, type TournamentMatch, type TournamentPlayer, type TournamentPlayerCount, type TournamentResult, type TournamentRound } from './tournament.ts';
import { compareResults } from './tournament-results.ts';

export function readTournamentPlayer(
  value: unknown,
  count: TournamentPlayerCount,
  allowNull = false,
): TournamentPlayer | null | undefined {
  if (allowNull && value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['name', 'seed']) ||
    typeof value.name !== 'string' ||
    !isNonnegativeSafeInteger(value.seed) ||
    value.seed < 1 ||
    value.seed > count ||
    value.name !== normalizeName(value.name) ||
    Array.from(value.name).length < 2 ||
    Array.from(value.name).length > 20
  )
    return undefined;
  return { name: value.name, seed: value.seed };
}

function readResult(value: unknown, size: number): TournamentResult | null | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['elapsedMs', 'moves']) ||
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves < size ** 2 / 2 ||
    value.moves > MOVES_MAX ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { elapsedMs: value.elapsedMs, moves: value.moves };
}

function readPair<T>(
  value: unknown,
  read: (entry: unknown) => T | null | undefined,
): readonly [T | null, T | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first = read(value[0]);
  const second = read(value[1]);
  if (first === undefined || second === undefined) return null;
  return [first, second];
}

export function readTournamentMatch(
  value: unknown,
  count: TournamentPlayerCount,
  size: number,
): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string'
  )
    return null;
  const parsed = parseBoardCode(value.boardCode);
  if (!parsed || parsed.size !== size) return null;
  const players = readPair(value.players, (entry) => readTournamentPlayer(entry, count, true));
  const results = readPair(value.results, (entry) => readResult(entry, size));
  const winner = readTournamentPlayer(value.winner, count, true);
  if (!players || !results || winner === undefined) return null;
  if (results.some((result, index) => result !== null && players[index] === null)) return null;
  if (winner) {
    if (!players[0] || !players[1] || !results[0] || !results[1]) return null;
    if (!samePlayer(winner, compareResults(players[0], results[0], players[1], results[1]))) return null;
  } else if (results[0] && results[1]) return null;
  return { boardCode: value.boardCode, players, results, winner };
}

export function readTournamentCurrent(
  value: unknown,
  rounds: readonly TournamentRound[],
): Tournament['current'] | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['match', 'round', 'turn']) ||
    !isNonnegativeSafeInteger(value.round) ||
    !isNonnegativeSafeInteger(value.match) ||
    (value.turn !== 0 && value.turn !== 1) ||
    !rounds[value.round]?.matches[value.match]
  )
    return undefined;
  return { match: value.match, round: value.round, turn: value.turn };
}

export function validTournamentPairings(
  entrants: readonly TournamentPlayer[],
  rounds: readonly TournamentRound[],
  count: TournamentPlayerCount,
): boolean {
  const first = rounds[0]?.matches;
  const pairs = openingSeedPairs(count);
  if (!first || first.length !== pairs.length) return false;
  for (let index = 0; index < pairs.length; index += 1) {
    const match = first[index]!;
    const pair = pairs[index]!;
    if (
      !sameNullablePlayer(match.players[0], entrants[pair[0] - 1]!) ||
      !sameNullablePlayer(match.players[1], entrants[pair[1] - 1]!)
    )
      return false;
  }
  for (let round = 1; round < rounds.length; round += 1) {
    for (let matchIndex = 0; matchIndex < rounds[round]!.matches.length; matchIndex += 1) {
      const previous = rounds[round - 1]!.matches;
      const match = rounds[round]!.matches[matchIndex]!;
      if (
        !sameNullablePlayer(match.players[0], previous[matchIndex * 2]?.winner ?? null) ||
        !sameNullablePlayer(match.players[1], previous[matchIndex * 2 + 1]?.winner ?? null)
      )
        return false;
    }
  }
  return true;
}

export function validTournamentProgress(tournament: Tournament): boolean {
  const positions = tournament.rounds.flatMap((round, roundIndex) =>
    round.matches.map((match, matchIndex) => ({ match, matchIndex, roundIndex })),
  );
  if (tournament.status === 'complete') {
    const finalWinner = tournament.rounds.at(-1)?.matches[0]?.winner;
    return (
      tournament.current === null &&
      tournament.champion !== null &&
      positions.every(({ match }) => match.winner !== null) &&
      !!finalWinner &&
      samePlayer(tournament.champion, finalWinner)
    );
  }
  const current = tournament.current;
  if (!current || tournament.champion !== null) return false;
  const currentIndex = positions.findIndex(
    (position) => position.roundIndex === current.round && position.matchIndex === current.match,
  );
  const activeMatch = positions[currentIndex]?.match;
  if (currentIndex < 0 || !activeMatch?.players[0] || !activeMatch.players[1]) return false;
  if (positions.slice(0, currentIndex).some(({ match }) => match.winner === null)) return false;
  if (positions.slice(currentIndex + 1).some(({ match }) => match.winner || match.results.some(Boolean))) return false;
  if (current.turn === 0) return !activeMatch.results[1] && !activeMatch.winner;
  return !!activeMatch.results[0] && (!activeMatch.winner || current.round < tournament.rounds.length - 1);
}

function samePlayer(first: TournamentPlayer, second: TournamentPlayer): boolean {
  return first.seed === second.seed && first.name === second.name;
}

function sameNullablePlayer(
  first: TournamentPlayer | null,
  second: TournamentPlayer | null,
): boolean {
  return first === null ? second === null : second !== null && samePlayer(first, second);
}

