import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  active = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const enabled = useRef(active);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      enabled.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    synchronize();
    enabled.current = active;
  }, [active]);

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [active, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}

import { parseBoardCode } from '../deck.ts';

export const TOURNAMENT_PLAYER_COUNTS = [4, 8] as const;
export type TournamentPlayerCount = (typeof TOURNAMENT_PLAYER_COUNTS)[number];

export interface TournamentPlayer {
  readonly name: string;
  readonly seed: number;
}

export interface TournamentResult {
  readonly elapsedMs: number;
  readonly moves: number;
}

export interface TournamentMatch {
  readonly boardCode: string;
  readonly players: readonly [TournamentPlayer | null, TournamentPlayer | null];
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winner: TournamentPlayer | null;
}

export interface TournamentRound {
  readonly matches: readonly TournamentMatch[];
  readonly name: 'Quarterfinal' | 'Semifinal' | 'Final';
  readonly size: number;
}

export interface TournamentPosition {
  readonly match: number;
  readonly round: number;
  readonly turn: 0 | 1;
}

export interface Tournament {
  readonly champion: TournamentPlayer | null;
  readonly current: TournamentPosition | null;
  readonly entrants: readonly TournamentPlayer[];
  readonly playerCount: TournamentPlayerCount;
  readonly rounds: readonly TournamentRound[];
  readonly status: 'active' | 'complete';
}

export interface TournamentDraft {
  readonly playerCount: TournamentPlayerCount;
  readonly players: readonly string[];
}

export type NameAcceptance =
  | { readonly error: 'Use 2 to 20 characters.' }
  | { readonly names: readonly string[] };

export interface RoundDefinition {
  readonly matchCount: number;
  readonly name: TournamentRound['name'];
  readonly size: number;
}

export function normalizeName(value: string): string {
  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function acceptPlayerNames(drafts: readonly string[], count: number): NameAcceptance {
  if (!isPlayerCount(count) || drafts.length < count) return { error: 'Use 2 to 20 characters.' };
  const names = drafts.slice(0, count).map(normalizeName);
  if (names.some((name) => {
    const length = Array.from(name).length;
    return length < 2 || length > 20;
  }))
    return { error: 'Use 2 to 20 characters.' };
  const folded = names.map((name) => name.toLowerCase());
  if (new Set(folded).size !== folded.length) return { error: 'Each name must be different.' };
  return { names };
}

export function isPlayerCount(value: number): value is TournamentPlayerCount {
  return value === 4 || value === 8;
}

export function roundDefinitions(count: TournamentPlayerCount): readonly RoundDefinition[] {
  return count === 4
    ? [
        { name: 'Semifinal', size: 6, matchCount: 2 },
        { name: 'Final', size: 8, matchCount: 1 },
      ]
    : [
        { name: 'Quarterfinal', size: 4, matchCount: 4 },
        { name: 'Semifinal', size: 6, matchCount: 2 },
        { name: 'Final', size: 8, matchCount: 1 },
      ];
}

export function openingSeedPairs(count: TournamentPlayerCount): readonly (readonly [number, number])[] {
  return count === 4 ? [[1, 4], [2, 3]] : [[1, 8], [4, 5], [3, 6], [2, 7]];
}

export function createTournament(
  playerCount: TournamentPlayerCount,
  names: readonly string[],
  boardCodes: readonly string[],
): Tournament | null {
  const accepted = acceptPlayerNames(names, playerCount);
  if (!('names' in accepted)) return null;
  const entrants = accepted.names.map((name, index) => ({ name, seed: index + 1 }));
  const definitions = roundDefinitions(playerCount);
  const neededCodes = definitions.reduce((sum, round) => sum + round.matchCount, 0);
  if (boardCodes.length !== neededCodes || new Set(boardCodes).size !== boardCodes.length) return null;
  let codeIndex = 0;
  const rounds = definitions.map((definition, roundIndex): TournamentRound => {
    const matches = Array.from({ length: definition.matchCount }, (_, matchIndex) => {
      const boardCode = boardCodes[codeIndex++];
      const parsed = boardCode ? parseBoardCode(boardCode) : null;
      if (!boardCode || !parsed || parsed.size !== definition.size) throw new Error('Invalid tournament deal.');
      const seeds = roundIndex === 0 ? openingSeedPairs(playerCount)[matchIndex] : null;
      return {
        boardCode,
        players: seeds
          ? [entrantAt(entrants, seeds[0]), entrantAt(entrants, seeds[1])]
          : [null, null],
        results: [null, null],
        winner: null,
      } as const;
    });
    return { matches, name: definition.name, size: definition.size };
  });
  return { champion: null, current: { round: 0, match: 0, turn: 0 }, entrants, playerCount, rounds, status: 'active' };
}

export function currentMatch(tournament: Tournament): TournamentMatch | null {
  const current = tournament.current;
  return current ? tournament.rounds[current.round]?.matches[current.match] ?? null : null;
}

export function currentPlayer(tournament: Tournament): TournamentPlayer | null {
  const current = tournament.current;
  const match = currentMatch(tournament);
  return current && match ? match.players[current.turn] : null;
}

export function currentResult(tournament: Tournament): TournamentResult | null {
  const current = tournament.current;
  const match = currentMatch(tournament);
  return current && match ? match.results[current.turn] : null;
}

function entrantAt(entrants: readonly TournamentPlayer[], seed: number): TournamentPlayer {
  const entrant = entrants[seed - 1];
  if (!entrant) throw new Error('Invalid tournament seed.');
  return entrant;
}
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { currentMatch } from './tournament.ts';
import type { Tournament, TournamentMatch, TournamentPlayer, TournamentPosition, TournamentResult, TournamentRound } from './tournament.ts';

export function compareResults(
  firstPlayer: TournamentPlayer,
  first: TournamentResult,
  secondPlayer: TournamentPlayer,
  second: TournamentResult,
): TournamentPlayer {
  if (first.moves !== second.moves) return first.moves < second.moves ? firstPlayer : secondPlayer;
  if (first.elapsedMs !== second.elapsedMs)
    return first.elapsedMs < second.elapsedMs ? firstPlayer : secondPlayer;
  return firstPlayer.seed > secondPlayer.seed ? firstPlayer : secondPlayer;
}

export function recordTournamentResult(
  tournament: Tournament,
  result: TournamentResult,
): Tournament {
  const position = tournament.current;
  const match = currentMatch(tournament);
  if (!position || !match || tournament.status !== 'active' || match.results[position.turn]) return tournament;
  if (
    !Number.isSafeInteger(result.moves) ||
    result.moves < tournament.rounds[position.round]!.size ** 2 / 2 ||
    result.moves > MOVES_MAX ||
    !Number.isFinite(result.elapsedMs) ||
    result.elapsedMs < 0 ||
    result.elapsedMs > ELAPSED_MAX_MS
  )
    return tournament;
  const results = [...match.results] as [TournamentResult | null, TournamentResult | null];
  results[position.turn] = result;
  if (!results[0] || !results[1]) return updateMatch(tournament, position, { ...match, results });

  const first = match.players[0];
  const second = match.players[1];
  if (!first || !second) return tournament;
  const winner = compareResults(first, results[0], second, results[1]);
  const updatedMatch = { ...match, results, winner };
  const updatedRounds = replaceMatch(tournament.rounds, position, updatedMatch);
  if (position.round === tournament.rounds.length - 1)
    return { ...tournament, champion: winner, current: null, rounds: updatedRounds, status: 'complete' };

  const nextRound = updatedRounds[position.round + 1];
  const nextMatchIndex = Math.floor(position.match / 2);
  const nextMatch = nextRound?.matches[nextMatchIndex];
  if (!nextRound || !nextMatch) return tournament;
  const players = [...nextMatch.players] as [TournamentPlayer | null, TournamentPlayer | null];
  players[position.match % 2] = winner;
  const advancedRound = {
    ...nextRound,
    matches: nextRound.matches.map((item, index) => (index === nextMatchIndex ? { ...item, players } : item)),
  };
  return {
    ...tournament,
    rounds: updatedRounds.map((round, index) => (index === position.round + 1 ? advancedRound : round)),
  };
}

export function advanceTournamentTurn(tournament: Tournament): Tournament {
  const position = tournament.current;
  const match = currentMatch(tournament);
  if (!position || position.turn !== 0 || !match?.results[0] || match.results[1]) return tournament;
  return { ...tournament, current: { ...position, turn: 1 } };
}

export function advanceTournamentMatch(tournament: Tournament): Tournament {
  const position = tournament.current;
  const match = currentMatch(tournament);
  if (!position || !match?.winner || tournament.status !== 'active') return tournament;
  const currentIndex = flatIndex(tournament.rounds, position.round, position.match);
  let nextIndex = 0;
  for (let round = 0; round < tournament.rounds.length; round += 1) {
    for (let index = 0; index < tournament.rounds[round]!.matches.length; index += 1) {
      if (nextIndex === currentIndex + 1)
        return { ...tournament, current: { round, match: index, turn: 0 } };
      nextIndex += 1;
    }
  }
  return tournament;
}

function updateMatch(tournament: Tournament, position: TournamentPosition, match: TournamentMatch): Tournament {
  return { ...tournament, rounds: replaceMatch(tournament.rounds, position, match) };
}

function replaceMatch(
  rounds: readonly TournamentRound[],
  position: TournamentPosition,
  match: TournamentMatch,
): readonly TournamentRound[] {
  return rounds.map((round, index) =>
    index === position.round
      ? { ...round, matches: round.matches.map((item, matchIndex) => (matchIndex === position.match ? match : item)) }
      : round,
  );
}

function flatIndex(rounds: readonly TournamentRound[], targetRound: number, targetMatch: number): number {
  let index = targetMatch;
  for (let round = 0; round < targetRound; round += 1) index += rounds[round]!.matches.length;
  return index;
}

import { currentMatch } from './tournament.ts';
import type { Tournament, TournamentPlayer, TournamentPosition, TournamentResult } from './tournament.ts';

export interface TournamentFeedback {
  readonly key: string;
  readonly number: number;
  readonly text: string;
}

export interface TournamentNotice {
  readonly message: string;
  readonly number: number;
}

export function tournamentStatusText(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: string,
): string {
  let base = '';
  if (tournament?.status === 'complete' && tournament.champion) base = `Champion: ${tournament.champion.name}.`;
  else if (tournament?.status === 'active' && match?.winner) base = `Match winner: ${match.winner.name}.`;
  else if (player && result) base = `${player.name} finished. Select ${current?.turn === 0 ? 'Next turn' : 'Next match'}.`;
  else if (player) base = `Now playing: ${player.name}${feedback.key === turnKey && feedback.text ? `. ${feedback.text}` : ''}`;
  if (notice) return base ? `${notice} ${base}` : notice;
  return base;
}

export function tournamentStatusKey(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: TournamentNotice,
): string {
  if (notice.message) return `notice-${notice.number}-${turnKey}-${feedback.key === turnKey ? feedback.number : 0}`;
  if (tournament?.status === 'complete') return `champion-${tournament.champion?.seed ?? 0}`;
  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}
import { parseBoardCode } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { acceptPlayerNames, createTournament, roundDefinitions, type Tournament, type TournamentPlayerCount } from './tournament.ts';

export type NewTournamentResult =
  | { readonly names: readonly string[]; readonly tournament: Tournament }
  | { readonly error: string };

export function newTournament(drafts: readonly string[], playerCount: TournamentPlayerCount): NewTournamentResult {
  const accepted = acceptPlayerNames(drafts, playerCount);
  if (!('names' in accepted)) return accepted;
  const sizes = roundDefinitions(playerCount).flatMap((round) =>
    Array.from({ length: round.matchCount }, () => round.size),
  );
  const boardCodes: string[] = [];
  const usedCodes = new Set<string>();
  let previousSeed: number | undefined;
  for (const size of sizes) {
    let code = freshBoardCode(size, previousSeed);
    while (usedCodes.has(code)) code = freshBoardCode(size, previousSeed);
    usedCodes.add(code);
    boardCodes.push(code);
    previousSeed = parseBoardCode(code)?.seed;
  }
  const tournament = createTournament(playerCount, accepted.names, boardCodes);
  return tournament ? { names: accepted.names, tournament } : { error: 'Could not start tournament.' };
}
