export function useTournament(onBack: () => void): TournamentController {
  const [store] = useState<TournamentStore | null>(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly Tournament[]>(initialHistory.items);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const play = useTournamentPlay();
  const turn = useRef<TournamentTurnHandle>(null);

  useEffect(() => {
    if (!play.saveWhenComplete || play.tournament?.status !== 'complete') return;
    const identity = encodeTournament({ draft: play.draft, gameSnapshot: null, tournament: play.tournament });
    const alreadySaved = history.some(
      (item) => encodeTournament({ draft: play.draft, gameSnapshot: null, tournament: item }) === identity,
    );
    if (!alreadySaved) {
      const next = [play.tournament, ...history].slice(0, 10);
      setHistory(next);
      setStorageAvailable(writeTournamentHistory(store, next));
    }
    play.setSaveWhenComplete(false);
  }, [history, play.draft, play.saveWhenComplete, play.setSaveWhenComplete, play.tournament, store]);

  const current = play.current;
  const match = play.match;
  const player = play.player;
  const result = play.result;
  const activeTurnKey = current ? `${current.round}-${current.match}-${current.turn}` : '';
  const turnKeyRef = useRef('');
  turnKeyRef.current = activeTurnKey;
  const exchange = useTournamentExchange({
    draft: play.draft,
    history,
    onBack,
    result,
    setAutoFocusBoard: play.setAutoFocusBoard,
    setDraft: play.setDraft,
    setGameFeedback: play.setGameFeedback,
    setGameSnapshot: play.setGameSnapshot,
    setSaveWhenComplete: play.setSaveWhenComplete,
    setStartButtonVisible: play.setStartButtonVisible,
    setTournament: play.setTournament,
    setTurnStarted: play.setTurnStarted,
    tournament: play.tournament,
    turnRef: turn,
    turnStarted: play.turnStarted,
  });
  const onFeedback = (text: string, number: number): void => {
    play.setGameFeedback({ key: turnKeyRef.current, number, text });
    exchange.clearNotice();
  };
  const startTournament = (): void => play.startTournament(exchange.publish, exchange.clearNotice);
  const turnAction = (): void => play.turnAction(exchange.clearNotice);

  const actionLabel = play.tournament?.status === 'active'
    ? match?.winner
      ? 'Next match'
      : current?.turn === 0 && match?.results[0]
        ? 'Next turn'
        : !play.turnStarted || play.startButtonVisible
          ? 'Start turn'
          : null
    : null;
  const status = tournamentStatusText(
    play.tournament,
    player,
    match,
    current,
    result,
    play.gameFeedback,
    activeTurnKey,
    exchange.notice.message,
  );
  const statusKey = tournamentStatusKey(
    play.tournament,
    player,
    match,
    current,
    result,
    play.gameFeedback,
    activeTurnKey,
    exchange.notice,
  );

  return {
    actionLabel,
    activeTurnKey,
    autoFocusBoard: play.autoFocusBoard,
    cancelDialog: exchange.cancelDialog,
    confirmDialog: exchange.confirmDialog,
    current,
    dialogAction: exchange.dialogAction,
    draft: play.draft,
    exportCurrent: exchange.exportCurrent,
    gameSnapshot: play.gameSnapshot,
    history,
    json: exchange.json,
    loadFromJson: exchange.loadFromJson,
    match,
    notice: exchange.notice.message,
    onBoardFocused: play.onBoardFocused,
    onComplete: play.onComplete,
    onFeedback,
    player,
    requestLeave: exchange.requestLeave,
    result,
    setDraft: play.setDraft,
    setJson: exchange.setJson,
    startButtonVisible: play.startButtonVisible,
    startTournament,
    status,
    statusKey,
    storageAvailable,
    tournament: play.tournament,
    turn,
    turnAction,
    turnStarted: play.turnStarted,
  };
}
import { formatElapsed } from '../elapsed-time.ts';
import { currentMatch } from './tournament.ts';
import type { Tournament, TournamentPlayer, TournamentPosition, TournamentResult } from './tournament.ts';

export interface TournamentFeedback {
  readonly key: string;
  readonly number: number;
  readonly text: string;
}

export interface TournamentNotice {
  readonly message: string;
  readonly number: number;
}

export function tournamentStatusText(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: string,
): string {
  let base = '';
  if (tournament?.status === 'complete' && tournament.champion) {
    const final = tournament.rounds.at(-1)?.matches[0];
    const championIndex = final?.players.findIndex((entrant) => entrant?.seed === tournament.champion?.seed) ?? -1;
    const championResult = final?.results[championIndex];
    base = championResult
      ? `Champion: ${tournament.champion.name}. ${championResult.moves} moves in ${formatElapsed(championResult.elapsedMs)}.`
      : `Champion: ${tournament.champion.name}.`;
  } else if (player && result) {
    const finished = `${player.name} finished with ${result.moves} moves in ${formatElapsed(result.elapsedMs)}.`;
    base = match?.winner
      ? `${finished} Match winner: ${match.winner.name}.`
      : `${finished} Select ${current?.turn === 0 ? 'Next turn' : 'Next match'}.`;
  } else if (player) {
    base = `Now playing: ${player.name}${feedback.key === turnKey && feedback.text ? `. ${feedback.text}` : ''}`;
  }
  if (notice) return base ? `${notice} ${base}` : notice;
  return base;
}

export function tournamentStatusKey(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: TournamentNotice,
): string {
  if (notice.message) return `notice-${notice.number}-${turnKey}-${feedback.key === turnKey ? feedback.number : 0}`;
  if (tournament?.status === 'complete') return `champion-${tournament.champion?.seed ?? 0}`;
  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}
import { hasExactKeys, isJsonObject, parseJson } from '../saved-format.ts';
import { isValidTournament } from './tournament-validation.ts';
import type { Tournament } from './tournament.ts';

export const TOURNAMENTS_KEY = 'np3:tournaments';
export const TOURNAMENTS_ENVELOPE_VERSION = 3;
export const TOURNAMENT_HISTORY_LIMIT = 10;

export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export interface TournamentHistoryRead {
  readonly available: boolean;
  readonly items: readonly Tournament[];
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistoryRead {
  if (!store) return { available: false, items: [] };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (text === null) return { available: true, items: [] };
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      !hasExactKeys(value, ['items', 'v']) ||
      value.v !== TOURNAMENTS_ENVELOPE_VERSION ||
      !Array.isArray(value.items) ||
      value.items.length > TOURNAMENT_HISTORY_LIMIT
    )
      return { available: true, items: [] };
    const items: Tournament[] = [];
    for (const item of value.items) {
      if (!isValidTournament(item) || item.status !== 'complete')
        return { available: true, items: [] };
      items.push(item);
    }
    return { available: true, items };
  } catch {
    return { available: false, items: [] };
  }
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  items: readonly Tournament[],
): boolean {
  if (!store) return false;
  try {
    const accepted = items.slice(0, TOURNAMENT_HISTORY_LIMIT);
    if (!accepted.every((item) => item.status === 'complete' && isValidTournament(item))) return false;
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ items: accepted, v: TOURNAMENTS_ENVELOPE_VERSION }));
    return true;
  } catch {
    return false;
  }
}

import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  active = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const enabled = useRef(active);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      enabled.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    synchronize();
    enabled.current = active;
  }, [active]);

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [active, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
