interface TournamentProgressProps {
  readonly controller: TournamentController;
}

export function TournamentProgress({ controller }: TournamentProgressProps) {
  const { current, match, player, tournament } = controller;
  const action = useRef<HTMLButtonElement>(null);
  const previousAction = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (controller.actionLabel === 'Start turn' && previousAction.current !== 'Start turn')
      action.current?.focus();
    previousAction.current = controller.actionLabel;
  }, [controller.actionLabel]);
  if (tournament?.status !== 'active' || !current || !match || !player) return null;
  return (
    <section className="tournament-play" aria-labelledby="tournament-play-title">
      <h3 id="tournament-play-title">Tournament match</h3>
      <p className="tournament-round">Round: {tournament.rounds[current.round]?.name}</p>
      <div className="tournament-action-row">
        {controller.actionLabel && (
          <button ref={action} className="control" type="button" onClick={controller.turnAction}>
            {controller.actionLabel}
          </button>
        )}
        <button className="control" type="button" onClick={controller.requestLeave}>Leave tournament</button>
      </div>
      {controller.turnStarted && (
        <TournamentTurn
          key={`${controller.activeTurnKey}-${controller.gameSnapshot ?? 'fresh'}`}
          ref={controller.turn}
          autoFocusBoard={controller.autoFocusBoard}
          boardCode={match.boardCode}
          initialSnapshot={controller.gameSnapshot}
          onBoardFocused={controller.onBoardFocused}
          onComplete={controller.onComplete}
          onFeedback={controller.onFeedback}
          player={player}
        />
      )}
      <TournamentBracket current={current} rounds={tournament.rounds} />
    </section>
  );
}
import { TOURNAMENT_PLAYER_COUNTS, type TournamentDraft } from './tournament.ts';

interface TournamentSetupProps {
  readonly draft: TournamentDraft;
  readonly onBack: () => void;
  readonly onDraftChange: (draft: TournamentDraft) => void;
  readonly onStart: () => void;
}

export function TournamentSetup({ draft, onBack, onDraftChange, onStart }: TournamentSetupProps) {
  function changePlayer(index: number, value: string): void {
    const players = [...draft.players];
    players[index] = value;
    onDraftChange({ ...draft, players });
  }

  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-title">
      <h3 id="tournament-setup-title">Set up a tournament</h3>
      <form onSubmit={(event) => { event.preventDefault(); onStart(); }}>
        <div className="tournament-player-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={draft.playerCount}
            onChange={(event) =>
              onDraftChange({ ...draft, playerCount: Number(event.currentTarget.value) as 4 | 8 })
            }
          >
            {TOURNAMENT_PLAYER_COUNTS.map((count) => (
              <option key={count} value={count}>{count}</option>
            ))}
          </select>
        </div>
        <fieldset className="tournament-name-fields">
          <legend>Player names</legend>
          {draft.players.slice(0, draft.playerCount).map((player, index) => (
            <div className="tournament-name-field" key={index}>
              <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
              <input
                id={`tournament-player-${index + 1}`}
                className="control"
                type="text"
                autoComplete="off"
                value={player}
                onChange={(event) => changePlayer(index, event.currentTarget.value)}
              />
            </div>
          ))}
        </fieldset>
        <div className="tournament-actions">
          <button className="control" type="submit">Start tournament</button>
          <button className="control" type="button" onClick={onBack}>Back to game</button>
        </div>
      </form>
    </section>
  );
}
import { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState } from 'react';
import { parseBoardCode } from '../deck.ts';
import { isWon } from '../game.ts';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { encodeSnapshot, decodeSnapshot } from '../snapshot.ts';
import { initialSession, activateSession } from '../session/session.ts';
import { useSessionClock } from '../session/use-session-clock.ts';
import type { Session } from '../session/session.ts';
import type { TournamentPlayer, TournamentResult } from './tournament.ts';

export interface TournamentTurnHandle {
  exportSnapshot(): string;
}

interface TournamentTurnProps {
  readonly autoFocusBoard: boolean;
  readonly boardCode: string;
  readonly initialSnapshot: string | null;
  readonly onBoardFocused: () => void;
  readonly onComplete: (result: TournamentResult) => void;
  readonly onFeedback: (feedback: string, announcement: number) => void;
  readonly player: TournamentPlayer;
}

export const TournamentTurn = forwardRef<TournamentTurnHandle, TournamentTurnProps>(
  function TournamentTurn(
    { autoFocusBoard, boardCode, initialSnapshot, onBoardFocused, onComplete, onFeedback, player },
    ref,
  ) {
    const [session, setSession] = useState(() => createTurnSession(boardCode, initialSnapshot));
    const current = useRef(session);
    const board = useRef<BoardFocus>(null);
    const onCompleteRef = useRef(onComplete);
    const onFeedbackRef = useRef(onFeedback);
    const onBoardFocusedRef = useRef(onBoardFocused);
    onCompleteRef.current = onComplete;
    onFeedbackRef.current = onFeedback;
    onBoardFocusedRef.current = onBoardFocused;

    function commit(next: Session): void {
      if (next === current.current) return;
      current.current = next;
      setSession(next);
    }

    const clock = useSessionClock(session, current, commit);
    const synchronizeRef = useRef(clock.synchronize);
    synchronizeRef.current = clock.synchronize;

    useImperativeHandle(
      ref,
      () => ({
        exportSnapshot() {
          synchronizeRef.current();
          return encodeSnapshot(current.current.game);
        },
      }),
      [],
    );

    useLayoutEffect(() => {
      if (!autoFocusBoard) return;
      board.current?.focusRemembered();
      onBoardFocusedRef.current();
    }, [autoFocusBoard]);

    useEffect(() => {
      if (session.announcement > 0 && session.feedback)
        onFeedbackRef.current(session.feedback, session.announcement);
    }, [session.announcement, session.feedback]);

    useEffect(() => {
      if (isWon(session.game))
        onCompleteRef.current({ elapsedMs: session.game.elapsedMs, moves: session.game.moves });
    }, [session.game.elapsedMs, session.game.matched.length, session.game.moves]);

    function activate(index: number): void {
      clock.synchronize();
      commit(activateSession(current.current, index));
    }

    return (
      <section className="tournament-turn" aria-labelledby="tournament-turn-title">
        <h3 id="tournament-turn-title">{player.name}'s game</h3>
        <GameStatus game={session.game} best={undefined} celebration={false} showBest={false} />
        <p id="tournament-board-help" className="help">
          Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
        </p>
        <Board
          key={session.generation}
          game={session.game}
          activate={activate}
          helpId="tournament-board-help"
          ref={board}
        />
      </section>
    );
  },
);

function createTurnSession(boardCode: string, snapshotText: string | null): Session {
  const restored = snapshotText ? decodeSnapshot(snapshotText) : null;
  const size = restored?.size ?? parseBoardCode(boardCode)?.size ?? 4;
  const session = initialSession(boardCode, { size, bestMoves: {} });
  return restored?.boardCode === boardCode ? { ...session, game: restored } : session;
}
