import { useState } from 'react';
import type { Dispatch, MutableRefObject, SetStateAction } from 'react';
import { decodeTournament, encodeTournament, TOURNAMENT_MAX_BYTES } from './tournament-format.ts';
import { findUnknownTournamentField } from './tournament-unknown-field.ts';
import type { Tournament, TournamentDraft, TournamentResult } from './tournament.ts';
import type { TournamentTurnHandle } from './TournamentTurn.tsx';

export type TournamentDialogAction = 'leave' | 'load' | null;

export interface TournamentExchangeOptions {
  readonly draft: TournamentDraft;
  readonly history: readonly Tournament[];
  readonly onBack: () => void;
  readonly result: TournamentResult | null;
  readonly setAutoFocusBoard: Dispatch<SetStateAction<boolean>>;
  readonly setDraft: Dispatch<SetStateAction<TournamentDraft>>;
  readonly setGameFeedback: Dispatch<SetStateAction<{ readonly key: string; readonly number: number; readonly text: string }>>;
  readonly setGameSnapshot: Dispatch<SetStateAction<string | null>>;
  readonly setSaveWhenComplete: Dispatch<SetStateAction<boolean>>;
  readonly setStartButtonVisible: Dispatch<SetStateAction<boolean>>;
  readonly setTournament: Dispatch<SetStateAction<Tournament | null>>;
  readonly setTurnStarted: Dispatch<SetStateAction<boolean>>;
  readonly tournament: Tournament | null;
  readonly turnRef: MutableRefObject<TournamentTurnHandle | null>;
  readonly turnStarted: boolean;
}

export function useTournamentExchange(options: TournamentExchangeOptions) {
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState({ message: '', number: 0 });
  const [dialogAction, setDialogAction] = useState<TournamentDialogAction>(null);
  const [pendingTransfer, setPendingTransfer] = useState<ReturnType<typeof decodeTournament>>(null);

  function publish(message: string): void {
    setNotice((previous) => ({ message, number: previous.number + 1 }));
  }

  function clearNotice(): void {
    setNotice((previous) => ({ ...previous, message: '' }));
  }

  function exportCurrent(): void {
    const tournament = options.tournament ?? options.history[0] ?? null;
    const gameSnapshot =
      options.tournament && options.result === null && options.turnStarted
        ? options.turnRef.current?.exportSnapshot() ?? null
        : null;
    const output = encodeTournament({ draft: options.draft, gameSnapshot, tournament });
    if (new TextEncoder().encode(output).byteLength > TOURNAMENT_MAX_BYTES) {
      publish('Tournament export is too large.');
      return;
    }
    setJson(output);
    publish('Tournament exported to the JSON box.');
  }

  function loadFromJson(): void {
    const unknownField = findUnknownTournamentField(json);
    if (unknownField) {
      publish(`Unknown field: ${unknownField}.`);
      return;
    }
    const transfer = decodeTournament(json);
    if (!transfer) {
      publish('Invalid tournament JSON.');
      return;
    }
    if (options.tournament?.status === 'active') {
      setPendingTransfer(transfer);
      setDialogAction('load');
      return;
    }
    applyTransfer(transfer);
  }

  function applyTransfer(transfer: NonNullable<ReturnType<typeof decodeTournament>>): void {
    options.setDraft(transfer.draft);
    options.setTournament(transfer.tournament);
    options.setGameSnapshot(transfer.gameSnapshot);
    options.setTurnStarted(transfer.gameSnapshot !== null);
    options.setStartButtonVisible(false);
    options.setAutoFocusBoard(false);
    options.setSaveWhenComplete(transfer.tournament !== null);
    options.setGameFeedback({ key: '', number: 0, text: '' });
    publish('Tournament loaded.');
  }

  function requestLeave(): void {
    setDialogAction('leave');
  }

  function cancelDialog(): void {
    setDialogAction(null);
    setPendingTransfer(null);
  }

  function confirmDialog(): void {
    const action = dialogAction;
    setDialogAction(null);
    if (action === 'leave') {
      options.setTournament(null);
      options.setGameSnapshot(null);
      options.setTurnStarted(false);
      options.setSaveWhenComplete(false);
      options.onBack();
      return;
    }
    if (action === 'load' && pendingTransfer) applyTransfer(pendingTransfer);
    setPendingTransfer(null);
  }

  return {
    cancelDialog,
    clearNotice,
    confirmDialog,
    dialogAction,
    exportCurrent,
    json,
    loadFromJson,
    notice,
    publish,
    requestLeave,
    setJson,
  };
}
import { isWon } from '../game.ts';
import { decodeSnapshot, SNAPSHOT_MAX_BYTES } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { currentMatch, isPlayerCount, type Tournament, type TournamentDraft } from './tournament.ts';
import { isValidTournament } from './tournament-validation.ts';

export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FORMAT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 65_536;

export interface TournamentTransfer {
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly tournament: Tournament | null;
}

export function encodeTournament(transfer: TournamentTransfer): string {
  const value = {
    draft: transfer.draft,
    format: TOURNAMENT_FORMAT,
    gameSnapshot: transfer.gameSnapshot,
    tournament: transfer.tournament,
    version: TOURNAMENT_FORMAT_VERSION,
  };
  return JSON.stringify(sortKeys(value), null, 2);
}

export function decodeTournament(text: string): TournamentTransfer | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['draft', 'format', 'gameSnapshot', 'tournament', 'version']) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    !validDraft(value.draft)
  )
    return null;
  if (value.tournament !== null && !isValidTournament(value.tournament)) return null;
  if (value.gameSnapshot !== null && typeof value.gameSnapshot !== 'string') return null;
  if (typeof value.gameSnapshot === 'string') {
    if (value.gameSnapshot.length > SNAPSHOT_MAX_BYTES) return null;
    const game = decodeSnapshot(value.gameSnapshot);
    const tournament = value.tournament as Tournament | null;
    const match = tournament ? currentMatch(tournament) : null;
    const position = tournament?.current;
    if (
      !game ||
      !tournament ||
      tournament.status !== 'active' ||
      !position ||
      !match ||
      match.results[position.turn] !== null ||
      game.boardCode !== match.boardCode
    )
      return null;
    // A completed snapshot is allowed only for the current unfinished attempt. Loading it will
    // record the same visible result through the ordinary completion boundary.
    if (isWon(game) && !game.started) return null;
  }
  return {
    draft: value.draft,
    gameSnapshot: value.gameSnapshot,
    tournament: value.tournament as Tournament | null,
  };
}

function validDraft(value: unknown): value is TournamentDraft {
  return (
    isJsonObject(value) &&
    hasExactKeys(value, ['playerCount', 'players']) &&
    typeof value.playerCount === 'number' &&
    isPlayerCount(value.playerCount) &&
    Array.isArray(value.players) &&
    value.players.length === 8 &&
    value.players.every((name) => typeof name === 'string')
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) sorted[key] = sortKeys((value as Record<string, unknown>)[key]);
  return sorted;
}
import { hasExactKeys, isJsonObject } from '../saved-format.ts';
import { roundDefinitions, type Tournament, type TournamentPlayer, type TournamentPlayerCount, type TournamentRound } from './tournament.ts';
import {
  readTournamentCurrent,
  readTournamentMatch,
  readTournamentPlayer,
  validTournamentPairings,
  validTournamentProgress,
} from './tournament-validation-entries.ts';

export function isValidTournament(value: unknown): value is Tournament {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['champion', 'current', 'entrants', 'playerCount', 'rounds', 'status']) ||
    (value.playerCount !== 4 && value.playerCount !== 8) ||
    (value.status !== 'active' && value.status !== 'complete') ||
    !Array.isArray(value.entrants) ||
    !Array.isArray(value.rounds)
  )
    return false;
  const playerCount = value.playerCount as TournamentPlayerCount;
  if (value.entrants.length !== playerCount) return false;
  const entrants = value.entrants.map((entry) => readTournamentPlayer(entry, playerCount));
  if (entrants.some((entry) => entry === undefined)) return false;
  const validEntrants = entrants as TournamentPlayer[];
  if (validEntrants.some((entry, index) => entry.seed !== index + 1)) return false;
  if (new Set(validEntrants.map((entry) => entry.name.toLowerCase())).size !== playerCount) return false;

  const definitions = roundDefinitions(playerCount);
  if (value.rounds.length !== definitions.length) return false;
  const usedCodes = new Set<string>();
  const rounds: TournamentRound[] = [];
  for (let roundIndex = 0; roundIndex < definitions.length; roundIndex += 1) {
    const rawRound = value.rounds[roundIndex];
    const definition = definitions[roundIndex]!;
    if (
      !isJsonObject(rawRound) ||
      !hasExactKeys(rawRound, ['matches', 'name', 'size']) ||
      rawRound.name !== definition.name ||
      rawRound.size !== definition.size ||
      !Array.isArray(rawRound.matches) ||
      rawRound.matches.length !== definition.matchCount
    )
      return false;
    const matches: TournamentRound['matches'][number][] = [];
    for (const rawMatch of rawRound.matches) {
      const match = readTournamentMatch(rawMatch, playerCount, definition.size);
      if (!match || usedCodes.has(match.boardCode)) return false;
      usedCodes.add(match.boardCode);
      matches.push(match);
    }
    rounds.push({ matches, name: definition.name, size: definition.size });
  }
  if (!validTournamentPairings(validEntrants, rounds, playerCount)) return false;

  const champion = readTournamentPlayer(value.champion, playerCount, true);
  const current = readTournamentCurrent(value.current, rounds);
  if (champion === undefined || current === undefined) return false;
  const tournament = {
    champion,
    current,
    entrants: validEntrants,
    playerCount,
    rounds,
    status: value.status,
  } as Tournament;
  return validTournamentProgress(tournament);
}

import { TOURNAMENT_PLAYER_COUNTS, type TournamentDraft } from './tournament.ts';

interface TournamentSetupProps {
  readonly draft: TournamentDraft;
  readonly onBack: () => void;
  readonly onDraftChange: (draft: TournamentDraft) => void;
  readonly onStart: () => void;
}

export function TournamentSetup({ draft, onBack, onDraftChange, onStart }: TournamentSetupProps) {
  function changePlayer(index: number, value: string): void {
    const players = [...draft.players];
    players[index] = value;
    onDraftChange({ ...draft, players });
  }

  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-title">
      <h3 id="tournament-setup-title">Set up a tournament</h3>
      <form onSubmit={(event) => { event.preventDefault(); onStart(); }}>
        <div className="tournament-player-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={draft.playerCount}
            onChange={(event) =>
              onDraftChange({ ...draft, playerCount: Number(event.currentTarget.value) as 4 | 8 })
            }
          >
            {TOURNAMENT_PLAYER_COUNTS.map((count) => (
              <option key={count} value={count}>{count}</option>
            ))}
          </select>
        </div>
        <fieldset className="tournament-name-fields">
          <legend>Player names</legend>
          {draft.players.slice(0, draft.playerCount).map((player, index) => (
            <div className="tournament-name-field" key={index}>
              <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
              <input
                id={`tournament-player-${index + 1}`}
                className="control"
                type="text"
                autoComplete="off"
                value={player}
                onChange={(event) => changePlayer(index, event.currentTarget.value)}
              />
            </div>
          ))}
        </fieldset>
        <div className="tournament-actions">
          <button className="control" type="submit">Start tournament</button>
          <button className="control" type="button" onClick={onBack}>Back to game</button>
        </div>
      </form>
    </section>
  );
}
import { useEffect, useRef } from 'react';
import type { SyntheticEvent } from 'react';

interface TournamentDialogProps {
  readonly action: 'leave' | 'load' | null;
  readonly onCancel: () => void;
  readonly onConfirm: () => void;
  readonly open: boolean;
}

export function TournamentDialog({ action, open, onCancel, onConfirm }: TournamentDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const element = dialog.current;
    if (open && element && !element.open) element.showModal();
    if (!open && element?.open) element.close();
  }, [open]);

  function cancel(event: SyntheticEvent<HTMLDialogElement>): void {
    event.preventDefault();
    onCancel();
  }

  return (
    <dialog
      ref={dialog}
      className="tournament-dialog"
      aria-labelledby="tournament-dialog-title"
      aria-describedby="tournament-dialog-description"
      onCancel={cancel}
    >
      <h3 id="tournament-dialog-title">
        {action === 'load' ? 'Load another tournament?' : 'Leave this unfinished tournament?'}
      </h3>
      <p id="tournament-dialog-description">
        {action === 'load'
          ? 'Your current tournament will be replaced by the tournament in the JSON box.'
          : 'Your current tournament will stop.'}
      </p>
      <div className="tournament-actions">
        <button className="control" type="button" autoFocus onClick={onCancel}>Keep playing</button>
        <button className="control" type="button" onClick={onConfirm}>
          {action === 'load' ? 'Load tournament' : 'Leave'}
        </button>
      </div>
    </dialog>
  );
}
