import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { normalizeName, openingSeedPairs, type Tournament, type TournamentMatch, type TournamentPlayer, type TournamentPlayerCount, type TournamentResult, type TournamentRound } from './tournament.ts';
import { compareResults } from './tournament-results.ts';

export function readTournamentPlayer(
  value: unknown,
  count: TournamentPlayerCount,
  allowNull = false,
): TournamentPlayer | null | undefined {
  if (allowNull && value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['name', 'seed']) ||
    typeof value.name !== 'string' ||
    !isNonnegativeSafeInteger(value.seed) ||
    value.seed < 1 ||
    value.seed > count ||
    value.name !== normalizeName(value.name) ||
    Array.from(value.name).length < 2 ||
    Array.from(value.name).length > 20
  )
    return undefined;
  return { name: value.name, seed: value.seed };
}

function readResult(value: unknown, size: number): TournamentResult | null | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['elapsedMs', 'moves']) ||
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves < size ** 2 / 2 ||
    value.moves > MOVES_MAX ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { elapsedMs: value.elapsedMs, moves: value.moves };
}

function readPair<T>(
  value: unknown,
  read: (entry: unknown) => T | null | undefined,
): readonly [T | null, T | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first = read(value[0]);
  const second = read(value[1]);
  if (first === undefined || second === undefined) return null;
  return [first, second];
}

export function readTournamentMatch(
  value: unknown,
  count: TournamentPlayerCount,
  size: number,
): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string'
  )
    return null;
  const parsed = parseBoardCode(value.boardCode);
  if (!parsed || parsed.size !== size) return null;
  const players = readPair(value.players, (entry) => readTournamentPlayer(entry, count, true));
  const results = readPair(value.results, (entry) => readResult(entry, size));
  const winner = readTournamentPlayer(value.winner, count, true);
  if (!players || !results || winner === undefined) return null;
  if (results.some((result, index) => result !== null && players[index] === null)) return null;
  if (winner) {
    if (!players[0] || !players[1] || !results[0] || !results[1]) return null;
    if (!samePlayer(winner, compareResults(players[0], results[0], players[1], results[1]))) return null;
  } else if (results[0] && results[1]) return null;
  return { boardCode: value.boardCode, players, results, winner };
}

export function readTournamentCurrent(
  value: unknown,
  rounds: readonly TournamentRound[],
): Tournament['current'] | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['match', 'round', 'turn']) ||
    !isNonnegativeSafeInteger(value.round) ||
    !isNonnegativeSafeInteger(value.match) ||
    (value.turn !== 0 && value.turn !== 1) ||
    !rounds[value.round]?.matches[value.match]
  )
    return undefined;
  return { match: value.match, round: value.round, turn: value.turn };
}

export function validTournamentPairings(
  entrants: readonly TournamentPlayer[],
  rounds: readonly TournamentRound[],
  count: TournamentPlayerCount,
): boolean {
  const first = rounds[0]?.matches;
  const pairs = openingSeedPairs(count);
  if (!first || first.length !== pairs.length) return false;
  for (let index = 0; index < pairs.length; index += 1) {
    const match = first[index]!;
    const pair = pairs[index]!;
    if (
      !sameNullablePlayer(match.players[0], entrants[pair[0] - 1]!) ||
      !sameNullablePlayer(match.players[1], entrants[pair[1] - 1]!)
    )
      return false;
  }
  for (let round = 1; round < rounds.length; round += 1) {
    for (let matchIndex = 0; matchIndex < rounds[round]!.matches.length; matchIndex += 1) {
      const previous = rounds[round - 1]!.matches;
      const match = rounds[round]!.matches[matchIndex]!;
      if (
        !sameNullablePlayer(match.players[0], previous[matchIndex * 2]?.winner ?? null) ||
        !sameNullablePlayer(match.players[1], previous[matchIndex * 2 + 1]?.winner ?? null)
      )
        return false;
    }
  }
  return true;
}

export function validTournamentProgress(tournament: Tournament): boolean {
  const positions = tournament.rounds.flatMap((round, roundIndex) =>
    round.matches.map((match, matchIndex) => ({ match, matchIndex, roundIndex })),
  );
  if (tournament.status === 'complete') {
    const finalWinner = tournament.rounds.at(-1)?.matches[0]?.winner;
    return (
      tournament.current === null &&
      tournament.champion !== null &&
      positions.every(({ match }) => match.winner !== null) &&
      !!finalWinner &&
      samePlayer(tournament.champion, finalWinner)
    );
  }
  const current = tournament.current;
  if (!current || tournament.champion !== null) return false;
  const currentIndex = positions.findIndex(
    (position) => position.roundIndex === current.round && position.matchIndex === current.match,
  );
  const activeMatch = positions[currentIndex]?.match;
  if (currentIndex < 0 || !activeMatch?.players[0] || !activeMatch.players[1]) return false;
  if (positions.slice(0, currentIndex).some(({ match }) => match.winner === null)) return false;
  if (positions.slice(currentIndex + 1).some(({ match }) => match.winner || match.results.some(Boolean))) return false;
  if (current.turn === 0) return !activeMatch.results[1] && !activeMatch.winner;
  return !!activeMatch.results[0] && (!activeMatch.winner || current.round < tournament.rounds.length - 1);
}

function samePlayer(first: TournamentPlayer, second: TournamentPlayer): boolean {
  return first.seed === second.seed && first.name === second.name;
}

function sameNullablePlayer(
  first: TournamentPlayer | null,
  second: TournamentPlayer | null,
): boolean {
  return first === null ? second === null : second !== null && samePlayer(first, second);
}
import { isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { TOURNAMENT_MAX_BYTES } from './tournament-format.ts';

interface ObjectShape {
  readonly fields: Readonly<Record<string, FieldShape>>;
}

interface ArrayShape {
  readonly arrayOf: FieldShape;
}

interface JsonStringShape {
  readonly jsonString: ObjectShape;
}

type FieldShape = ObjectShape | ArrayShape | JsonStringShape | ((value: unknown) => FieldShape) | null;

const object = (fields: Readonly<Record<string, FieldShape>>): ObjectShape => ({ fields });
const array = (arrayOf: FieldShape): ArrayShape => ({ arrayOf });
const jsonString = (json: ObjectShape): JsonStringShape => ({ jsonString: json });

const player = object({ name: null, seed: null });
const result = object({ elapsedMs: null, moves: null });
const current = object({ match: null, round: null, turn: null });
const selection = (value: unknown): FieldShape => {
  if (!isJsonObject(value)) return null;
  if (value.kind === 'closed') return object({ kind: null });
  if (value.kind === 'one') return object({ index: null, kind: null });
  if (value.kind === 'mismatch')
    return object({ first: null, kind: null, remainingMs: null, second: null });
  return object({ kind: null });
};
const snapshot = object({
  boardCode: null,
  elapsedMs: null,
  matched: null,
  moves: null,
  selection,
  started: null,
  version: null,
});
const match = object({
  boardCode: null,
  players: array(player),
  results: array(result),
  winner: player,
});
const round = object({ matches: array(match), name: null, size: null });
const tournament = object({
  champion: player,
  current,
  entrants: array(player),
  playerCount: null,
  rounds: array(round),
  status: null,
});
const transfer = object({
  draft: object({ playerCount: null, players: null }),
  format: null,
  gameSnapshot: jsonString(snapshot),
  tournament,
  version: null,
});

export function findUnknownTournamentField(text: string): string | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  return findUnknown(parseJson(text), transfer);
}

function findUnknown(value: unknown, shape: FieldShape): string | null {
  if (typeof shape === 'function') return findUnknown(value, shape(value));
  if (shape === null) return null;
  if ('arrayOf' in shape) {
    if (!Array.isArray(value)) return null;
    for (const item of value) {
      const unknown = findUnknown(item, shape.arrayOf);
      if (unknown) return unknown;
    }
    return null;
  }
  if ('jsonString' in shape) {
    if (typeof value !== 'string') return null;
    return findUnknown(parseJson(value), shape.jsonString);
  }
  if (!isJsonObject(value)) return null;
  for (const key of Object.keys(value)) {
    if (!Object.hasOwn(shape.fields, key)) return key;
  }
  for (const key of Object.keys(value)) {
    const childShape = shape.fields[key];
    if (childShape === undefined) continue;
    const unknown = findUnknown(value[key], childShape);
    if (unknown) return unknown;
  }
  return null;
}
import { parseBoardCode } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { acceptPlayerNames, createTournament, roundDefinitions, type Tournament, type TournamentPlayerCount } from './tournament.ts';

export type NewTournamentResult =
  | { readonly names: readonly string[]; readonly tournament: Tournament }
  | { readonly error: string };

export function newTournament(drafts: readonly string[], playerCount: TournamentPlayerCount): NewTournamentResult {
  const accepted = acceptPlayerNames(drafts, playerCount);
  if (!('names' in accepted)) return accepted;
  const sizes = roundDefinitions(playerCount).flatMap((round) =>
    Array.from({ length: round.matchCount }, () => round.size),
  );
  const boardCodes: string[] = [];
  const usedCodes = new Set<string>();
  let previousSeed: number | undefined;
  for (const size of sizes) {
    let code = freshBoardCode(size, previousSeed);
    while (usedCodes.has(code)) code = freshBoardCode(size, previousSeed);
    usedCodes.add(code);
    boardCodes.push(code);
    previousSeed = parseBoardCode(code)?.seed;
  }
  const tournament = createTournament(playerCount, accepted.names, boardCodes);
  return tournament ? { names: accepted.names, tournament } : { error: 'Could not start tournament.' };
}

import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: { ...session.preferences, size: game.size },
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}
import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
